  "city.doppel-parlor.description": "多佩尔中央研究所一侧的会客室。客人入座后，研究日志会一页一页递过来。",
  "city.doppel-lab.description": "位于多佩尔研究所深处的内部研究机构。曾被派往以太纳的研究员们留下的日记汇集于此。",
  "city.doppel-lab.displayName": "多佩尔 · 内部研究机构",
  "city.doppel-office.description": "汇总研究成果与遗物用途的多佩尔管理部。审批要经过层层关卡，需要等很久。",
  "city.doppel-office.displayName": "多佩尔 · 管理部",
  "city.rust-garage.description": "拉斯特的维修场。请求修理损坏研究设备的委托接连不断。",
  "city.rust-garage.displayName": "拉斯特 · 维修场",
  "city.rust-lease.description": "出租高性能设备的拉斯特租赁管理部。就连一次续租也要经过漫长的谈判。",
  "city.rust-lease.displayName": "拉斯特 · 租赁管理部",
  "city.doppel-upper.description": "多佩尔研究所的最高层。决定研究目的的人坐在这里。",
  "city.doppel-upper.displayName": "多佩尔 · 上层部",
  "city.rust-works.description": "矗立在拉斯特中心的巨大工坊。研究设备的设计与维修都汇聚于此。",
  "city.rust-works.displayName": "拉斯特 · 中央工坊",
  "city.odidi-embassy.description": "研究梦境的都市奥迪迪迎接外来宾客的接见室。提议总是由他们先开口。",
  "city.odidi-embassy.displayName": "奥迪迪 · 外交接见室",
