  "shopClerk.obi.name": "欧比",
  "shopClerk.protia.name": "普罗缇娅",
  "shopClerk.haine.name": "海涅",
  "journal.interaction-doppel-01.title": "蓝色走廊的告示牌",
  "journal.interaction-doppel-01.body": "温室的第一块告示牌上，仍写着请将复原体当作新邻居而非展览品来欢迎。",
  "journal.interaction-doppel-02.title": "重复的问候",
  "bond.torika.0": "你是谁？",
  "bond.torika.1": "你又来了。",
  "bond.torika.2": "可以待在我身边。",
  "bond.torika.3": "今天要做什么呢？",
  "bond.torika.4": "我认得你的脚步声。",
  "bond.torika.5": "和你在一起，心里很平静。",
  "bond.torika.6": "你的背后交给我。",
  "bond.torika.7": "我一直在等你。",
  "bond.torika.8": "你来了我就安心。",
  "bond.torika.9": "我会陪你走到最后。",
  "bond.torika.10": "我们的庭园，由我来守护。",
  "bond.rex.0": "别碰我。",
  "bond.rex.1": "不怕吗？",
  "bond.rex.2": "有点意思。",
  "bond.rex.3": "下次狩猎也来吧。",
  "bond.rex.4": "我记住你的气味了。",
  "bond.rex.5": "别离开我身边。",
  "bond.rex.6": "冲你来的，我全咬回去。",
  "bond.rex.7": "今天又迟到了。",
  "bond.rex.8": "比起命令，我更喜欢你的声音。",
  "bond.rex.9": "你是我唯一的族群。",
  "bond.rex.10": "我会永远站在你这边。",
  "bond.spino.0": "……什么事？",
  "bond.spino.1": "好想念水啊。",
  "bond.spino.2": "安静待着也没关系。",
  "bond.spino.3": "再多讲讲你的事吧。",
  "bond.spino.4": "今天的浪很平静。",
  "bond.spino.5": "我喜欢一起散步。",
  "bond.spino.6": "危险的话就躲到我身后。",
  "bond.spino.7": "我就知道你会来。",
  "bond.spino.8": "我已经习惯这座城市了。",
  "bond.spino.9": "你的身边就是我的水。",
  "bond.spino.10": "一起流向任何地方吧。",
  "bond.generic.0": "还是有点陌生。",
  "bond.generic.1": "今天又见面了。",
  "bond.generic.2": "正一点一点习惯。",
  "bond.generic.3": "一起去执行任务吧。",
  "bond.generic.4": "你来了我很高兴。",
  "bond.generic.5": "可以待在我身边。",
  "bond.generic.6": "这次也会帮忙的。",
  "bond.generic.7": "我一直在等你。",
  "bond.generic.8": "我们是好伙伴。",
  "bond.generic.9": "想和你一直在一起。",
  "bond.generic.10": "今后也拜托你了。",
