  "observation.luka-sofa-conversation.prompt": "研究员在研究室沙发上跟卢卡搭话时，他会怎么反应？",
  "observation.luka-sofa-conversation.luka-sofa-silence.label": "让出位置，并肩享受自在的沉默",
