  "relic.raitia-grass.origin": "睡鼠",
  "relic.raitia-grass.excavationSite": "斯洛文尼亚 喀斯特洞穴沉积层",
  "relic.raitia-grass.fossilRecord": "从洞穴沉积物的同一层中回收了数十个同种头骨。其中五个在大小与齿列上高度一致，被归为同一窝。",
  "relic.raitia-grass.catalogSummary": "以睡鼠为基础，复原出过大门齿与颊囊的个体。",
  "relic.raitia-grass.squadNote": "歼灭的消耗性兵力。她们朝指向的方向一齐涌去填满走廊，后面的直接踏过前面倒下的地方。",
  "relic.raitia-grass.researcherTitle": "研究员",
  "relic.raitia-grass.unlockRecord": "识别记录207。已确认隶属于歼灭。在五个穿着带鼠耳兜帽睡衣的个体中，这只系着绿色绳结，奶酪形小包、带牙齿的拖鞋以及末端系着缎带的条纹尾巴格外显眼。找到食物时，它不是用叫声而是用门齿的声音传讯，听到的姐妹们一齐涌向同一处。它啃过的地方散落着新芽，走过的路上每个脚印都长出种子的嫩芽，留下一条绿色的道路。到了该冬眠的时候仍不停止进食的原因，尚未确认。",
  "relic.raitia-grass.observation.originYear": "约200万年前",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "幼年",
  "relic.raitia-grass.observation.height": "0.94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "冬眠",
  "relic.raitia-grass.passive.desc": "每场战斗一次，生命降至一半以下时，5秒内每秒恢复最大生命的3%。",
