  "relic.raitia-water.origin": "睡鼠",
  "relic.raitia-water.excavationSite": "斯洛文尼亚 喀斯特洞穴沉积层",
  "relic.raitia-water.fossilRecord": "从洞穴沉积物的同一层中回收了数十个同种头骨。其中五个在大小与齿列上高度一致，被归为同一窝。",
  "relic.raitia-water.catalogSummary": "以睡鼠为基础，复原出过大门齿与颊囊的个体。",
  "relic.raitia-water.squadNote": "歼灭的消耗性兵力。她们朝指向的方向一齐涌去填满走廊，后面的直接踏过前面倒下的地方。",
  "relic.raitia-water.researcherTitle": "研究员",
  "relic.raitia-water.unlockRecord": "识别记录208。已确认隶属于歼灭。在同样的带兜帽睡衣中，这只的蓝色条纹尾巴末端系着棉球，一只手叉腰，另一只手的手指抵在嘴边微笑。听到姐妹的门齿声时，它笑着第一个冲出来，靠近后先用门齿啃手边够得着的装备。群体走过的地方留下了长长的湿脚印。是什么打湿了那些脚印，尚未确认。",
  "relic.raitia-water.observation.originYear": "约200万年前",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
