  "relic.raitia-fire.fossilRecord": "从洞穴沉积物的同一层中回收了数十个同种头骨。其中五个在大小与齿列上高度一致，被归为同一窝。",
  "relic.raitia-fire.catalogSummary": "以睡鼠为基础，复原出过大门齿与颊囊的个体。",
  "relic.raitia-fire.squadNote": "歼灭的消耗性兵力。她们朝指向的方向一齐涌去填满走廊，后面的直接踏过前面倒下的地方。",
  "relic.raitia-fire.researcherTitle": "研究员",
  "relic.raitia-fire.unlockRecord": "识别记录209。已确认隶属于歼灭。在同样的带兜帽睡衣中，这只戴着粉色格纹缎带，带着没睡醒的脸站着，一只手揉眼睛，另一只手叉腰。尽管一脸困意，它也没有停止进食，颊囊塞满之后仍用门齿啃个不停。姐妹们涌过去时，它揉着眼睛跟在后面。这份困倦是装的还是真的，尚未确认。",
  "relic.raitia-fire.observation.originYear": "约200万年前",
