  "relic.raitia-earth.catalogSummary": "以睡鼠为基础，复原出过大门齿与颊囊的个体。",
  "relic.raitia-earth.squadNote": "歼灭的消耗性兵力。她们朝指向的方向一齐涌去填满走廊，后面的直接踏过前面倒下的地方。",
  "relic.raitia-earth.researcherTitle": "研究员",
  "relic.raitia-earth.unlockRecord": "识别记录210。已确认隶属于歼灭。在同样的带兜帽睡衣中，这只以棕色底色、黄色绳结和麻花辫最为显眼，尾巴末端挂着一大团毛球。它向前伸出手站立时，姐妹们会一齐朝着它指尖的方向涌去，前面的个体倒下的地方，后面的个体直接踩过去。是谁决定了它指尖所指的方向，尚未确认。",
