  "relic.raitia-wind.catalogSummary": "以睡鼠为基础，复原出过大门齿与颊囊的个体。",
  "relic.raitia-wind.squadNote": "歼灭的消耗性兵力。她们朝指向的方向一齐涌去填满走廊，后面的直接踏过前面倒下的地方。",
  "relic.raitia-wind.researcherTitle": "研究员",
  "relic.raitia-wind.unlockRecord": "识别记录211。确认隶属于歼灭。是同样穿着连帽睡衣的姐妹中系着薄荷色丝带的个体，抱着胳膊、紧闭着嘴站着。直到姐妹们涌向食物之后，她才勉强跟了过去，到了之后却是啃动门齿最久的一个。从未观察到她用门齿的声音传达过任何信息。",
